// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        string memory returned;
        try c.version() returns (string memory v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = "";
        }

        assertTrue(ok && (keccak256(bytes(returned)) == keccak256(bytes("1.0.0"))));
    }
}
